function calculatePrice(raw: number) {
  // renamed variable and removed obsolete comment
  const basePrice = raw;
  const finalPrice = Math.round(basePrice * 1.2);
  return finalPrice;
}

// file: shipping.ts
function estimatedDelivery(days: number) {
  // renamed param and changed business rule from 3 to 2 days
  if (days < 2) return 'soon';
  return 'standard';
}

// Version A
function calculateTotal(items: Item[]) {
  // small rename and clarified comment
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  return subtotal * (1 - getDiscount());
}

// Version B
function total(items: Item[]) {
  // large inline refactor and formatting changes across logic
  let s = 0;
  for (const i of items) { s += i.price * i.qty; }
  return s * (1 - getDiscount());
}
